package com.peopleai.jobs.controller;
import com.peopleai.jobs.model.Job;import com.peopleai.jobs.repository.JobRepository;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;import java.util.Map;
@RestController @RequestMapping("/api/jobs") @CrossOrigin(origins="*") public class JobsController {private final JobRepository repo;public JobsController(JobRepository r){repo=r;}@GetMapping public List<Job> all(){return repo.findAll();}@GetMapping("/{id}") public Job one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Job create(@Valid @RequestBody Job x){return repo.save(x);}@PutMapping("/{id}")public Job update(@PathVariable Long id,@Valid @RequestBody Job x){Job j=one(id);j.setTitle(x.getTitle());j.setLocation(x.getLocation());j.setSalary(x.getSalary());j.setStatus(x.getStatus());j.setDescription(x.getDescription());return repo.save(j);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){repo.delete(one(id));}@GetMapping("/health")public Map<String,String> health(){return Map.of("status","UP");}}
